<?php
require 'helpers.php';
requerirLogin();
if (!puede('ver_dashboard')) { http_response_code(403); exit('No tenés permiso para usar el simulador.'); }
$paginaActual = 'simulador';
$clienteId = (int)usuario()['cliente_id'];

$st = db()->prepare('SELECT id,nombre,unidad,moneda,volumen_esperado,horas_trabajo,valor_hora,margen_porcentaje,precio_manual FROM costobene_productos WHERE cliente_id=? ORDER BY nombre');
$st->execute([$clienteId]);
$productos = $st->fetchAll();
$cfg = db()->prepare('SELECT periodo_activo,moneda FROM costobene_configuraciones_app WHERE cliente_id=?');
$cfg->execute([$clienteId]);
$config = $cfg->fetch() ?: ['periodo_activo'=>'month','moneda'=>'ARS'];
$periodos = ['day'=>'día','week'=>'semana','month'=>'mes','year'=>'año'];
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['accion'] ?? '') === 'guardar_configuracion_simulador') {
    try {
        validarCsrf('csrf_sim_config');
        $periodoNuevo = (string)($_POST['periodo_activo'] ?? '');
        $monedaNueva = strtoupper((string)($_POST['moneda_config'] ?? ''));
        if (!array_key_exists($periodoNuevo, $periodos) || !in_array($monedaNueva, ['ARS','USD','EUR'], true)) throw new RuntimeException('Seleccioná un período y una moneda válidos.');
        $save = db()->prepare('INSERT INTO costobene_configuraciones_app (cliente_id,periodo_activo,moneda) VALUES (?,?,?) ON DUPLICATE KEY UPDATE periodo_activo=VALUES(periodo_activo),moneda=VALUES(moneda)');
        $save->execute([$clienteId,$periodoNuevo,$monedaNueva]);
        header('Location: simulador.php?config=guardada'); exit;
    } catch (Throwable $e) { $errorConfig = $e instanceof RuntimeException ? $e->getMessage() : 'No se pudo guardar la configuración del simulador.'; }
}
$errorConfig = $errorConfig ?? '';

$comQ = db()->prepare('SELECT id,nombre,categoria,porcentaje,cargo_fijo,moneda,iva_porcentaje,producto_id,base_calculo FROM costobene_comisiones WHERE cliente_id=? AND activa=1 ORDER BY categoria,nombre');
$comQ->execute([$clienteId]); $comisiones = $comQ->fetchAll();
$promoQ = db()->prepare("SELECT p.* FROM costobene_promociones p WHERE p.cliente_id=? AND p.estado<>'pausada' AND p.fecha_inicio<=CURDATE() AND p.fecha_fin>=CURDATE() ORDER BY p.id DESC");
$promoQ->execute([$clienteId]); $promociones = $promoQ->fetchAll();
$promoProductos = [];
if ($promociones) {
    $idsPromo = array_column($promociones, 'id'); $ph = implode(',', array_fill(0, count($idsPromo), '?'));
    $mapQ = db()->prepare("SELECT promocion_id,producto_id FROM costobene_promociones_productos WHERE promocion_id IN ($ph)");
    $mapQ->execute($idsPromo);
    foreach ($mapQ as $m) $promoProductos[(int)$m['promocion_id']][] = (int)$m['producto_id'];
}

$costosProducto = [];
foreach ($productos as $p) {
    $q = db()->prepare("SELECT c.tipo_costo, COALESCE(SUM(COALESCE(m.monto_asignado,c.monto)),0) total
        FROM costobene_costos_producto c
        LEFT JOIN costobene_costos_productos_compartidos m ON m.costo_id=c.id AND m.producto_id=?
        WHERE c.estado_aprobacion='aprobado'
          AND (m.producto_id IS NOT NULL OR (c.producto_id=? AND NOT EXISTS (SELECT 1 FROM costobene_costos_productos_compartidos mx WHERE mx.costo_id=c.id)))
        GROUP BY c.tipo_costo");
    $q->execute([(int)$p['id'],(int)$p['id']]);
    $sum = ['fixed'=>0.0,'variable'=>0.0,'indirect'=>0.0,'labor'=>0.0];
    foreach ($q->fetchAll() as $r) $sum[$r['tipo_costo']] = (float)$r['total'];
    // Las horas propias se mantienen separadas para que no se dupliquen con la mano de obra ya registrada.
    $costosProducto[(int)$p['id']] = $sum;
}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Simulador - CostoPyme</title><link rel="stylesheet" href="style.css"><style>
.sim-meta{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 14px}.sim-meta span{background:#f1f5f9;border:1px solid #e2e8f0;border-radius:20px;padding:6px 10px;font-size:12px;color:#475569}.scenario-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.scenario-card{border:1px solid #dbe3ed;border-radius:12px;padding:15px;min-width:0}.scenario-card h3{margin:0 0 12px;color:#1e3a5f}.scenario-card .form-grid{grid-template-columns:1fr 1fr;gap:10px}.scenario-card label{font-size:12px}.scenario-card input{padding:8px;font-size:13px}.scenario-card .full{grid-column:1/-1}.method-note{border-left:3px solid #315d9d;padding:9px 12px;background:#f8fafc;color:#475569;font-size:12px;margin-top:12px}.scenario-result{border:1px solid #dbe3ed;border-radius:11px;padding:13px}.scenario-result h3{margin:0 0 10px}.scenario-result .kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.scenario-result .kpi b{font-size:16px;overflow-wrap:anywhere}.chart-row{display:grid;grid-template-columns:125px 1fr 105px;align-items:center;gap:10px;margin:11px 0;font-size:12px}.chart-track{height:15px;border-radius:20px;background:#e2e8f0;overflow:hidden}.chart-bar{height:100%;border-radius:20px;background:#315d9d;min-width:2px}.chart-bar.loss{background:#c2414b}.validation{display:none}.validation.show{display:block}.sim-table td,.sim-table th{white-space:nowrap}@media(max-width:1000px){.scenario-grid{grid-template-columns:1fr 1fr}}@media(max-width:650px){.scenario-grid{grid-template-columns:1fr}.scenario-card .form-grid{grid-template-columns:1fr 1fr}.chart-row{grid-template-columns:90px 1fr 80px;gap:6px}.scenario-result .kpis{grid-template-columns:1fr 1fr}}
</style></head><body><div class="app-shell"><?php require 'menu.php';?><main class="main">
<header class="page-head"><div><h1>Simulador de costos y rentabilidad</h1><p>Calculá costo total, costo unitario, precio sugerido y punto de equilibrio. Compará tres escenarios sin modificar tus registros.</p></div></header>
<section class="panel"><h2>Configuración del cálculo</h2><?php if(isset($_GET['config'])):?><div class="success">La configuración del período y la moneda se guardó correctamente.</div><?php endif;?><?php if($errorConfig):?><div class="error"><?=h($errorConfig)?></div><?php endif;?>
<form method="post" class="form-grid" style="margin-bottom:14px"><input type="hidden" name="csrf" value="<?=h(csrfToken('csrf_sim_config'))?>"><input type="hidden" name="accion" value="guardar_configuracion_simulador"><label>Período de análisis<select name="periodo_activo"><?php foreach($periodos as $key=>$label):?><option value="<?=h($key)?>" <?=$config['periodo_activo']===$key?'selected':''?>>Por <?=h($label)?></option><?php endforeach;?></select></label><label>Moneda predeterminada<select name="moneda_config"><?php foreach(['ARS'=>'ARS - Pesos','USD'=>'USD - Dólares','EUR'=>'EUR - Euros'] as $key=>$label):?><option value="<?=h($key)?>" <?=$config['moneda']===$key?'selected':''?>><?=h($label)?></option><?php endforeach;?></select></label><div class="actions" style="align-self:end"><button type="submit">Guardar configuración</button></div></form>
<div class="sim-meta"><span>Período aplicado: <b><?=h($periodos[$config['periodo_activo']]??'mes')?></b></span><span>Moneda predeterminada: <b><?=h($config['moneda'])?></b></span><span>Los costos aprobados se importan del catálogo</span></div>
<div class="form-grid"><label class="full">Producto o servicio registrado<select id="producto"><option value="">Simulación manual</option><?php foreach($productos as $p):?><option value="<?=(int)$p['id']?>"><?=h($p['nombre'])?> · <?=h($p['unidad'])?> · <?=h($p['moneda'])?></option><?php endforeach;?></select></label><label>Nombre de referencia<input id="nombre" maxlength="100" placeholder="Ej. Servicio de diseño"></label><label>Unidad de venta<input id="unidad" maxlength="50" value="unidad" placeholder="unidad, kg, hora, servicio"></label><label>Moneda<select id="moneda"><option value="ARS">ARS - Pesos</option><option value="USD">USD - Dólares</option><option value="EUR">EUR - Euros</option></select></label></div>
<div class="method-note">Los costos fijos, indirectos y de mano de obra se interpretan como totales del período seleccionado. El costo variable se interpreta como importe por unidad de venta. Los costos pendientes de aprobación no se incluyen. Si cambiás el período, revisá los importes cargados: no se convierten automáticamente.</div></section>
<section class="panel"><h2>Escenarios comparables</h2><p class="help">Completá los valores para cada escenario. El escenario base se precarga con los costos aprobados del producto elegido; los otros dos se pueden modificar para probar cambios.</p>
<div class="scenario-grid" id="scenarioGrid">
<?php for($i=1;$i<=3;$i++):?><article class="scenario-card" data-scenario="<?=$i?>"><h3><?=$i===1?'Escenario 1 · Base':($i===2?'Escenario 2 · Alternativo':'Escenario 3 · Alternativo')?></h3><div class="form-grid">
<label>Volumen del período<input type="number" min="0" step="0.01" data-field="volumen" value="100"></label>
<label>Margen esperado (%)<input type="number" min="0" max="90" step="0.01" data-field="margen" value="30"></label>
<label>Costos fijos del período<input type="number" min="0" step="0.01" data-field="fijos" value="0"></label>
<label>Variables por unidad<input type="number" min="0" step="0.01" data-field="variable" value="0"></label>
<label>Costos indirectos del período<input type="number" min="0" step="0.01" data-field="indirectos" value="0"></label>
<label>Mano de obra registrada (período)<input type="number" min="0" step="0.01" data-field="laborRegistrada" value="0"></label>
<label>Horas de trabajo propio<input type="number" min="0" step="0.01" data-field="horas" value="0"></label>
<label>Valor por hora<input type="number" min="0" step="0.01" data-field="valorHora" value="0"></label>
<label>Precio manual alternativo<input type="number" min="0" step="0.01" data-field="precioManual" placeholder="Vacío = sugerido"></label>
</div><p class="help">Si dejás el precio manual vacío, se calcula automáticamente a partir del costo unitario y el margen esperado.</p></article><?php endfor;?>
</div>
<section class="panel" style="margin-top:16px"><h2>Promociones y comisiones (opcional)</h2><p class="help">Estas condiciones comerciales se aplican por igual a los tres escenarios. Las promociones solo pueden aplicarse a productos registrados.</p><div class="form-grid"><label>Promoción vigente<select id="promocionSim"><option value="">Sin promoción</option><?php foreach($promociones as $pr):?><option value="<?=(int)$pr['id']?>" data-tipo="<?=h($pr['tipo'])?>" data-valor="<?=h($pr['valor'])?>" data-minimo="<?=h($pr['cantidad_minima']??'')?>" data-bonif="<?=h($pr['cantidad_bonificada']??'')?>" data-alcance="<?=h($pr['alcance'])?>" data-futuros="<?=(int)$pr['incluir_futuros']?>" data-productos="<?=h(implode(',', $promoProductos[(int)$pr['id']]??[]))?>"><?=h($pr['nombre'])?> · <?=h($pr['tipo'])?></option><?php endforeach;?></select></label><label>Operaciones / transacciones por período<input id="operacionesSim" type="number" min="0" step="1" value="1"></label><div class="full"><b>Comisiones aplicables</b><?php if(!$comisiones):?><p class="help">No hay comisiones configuradas. Podés agregarlas desde Costos.</p><?php else:?><div class="commission-options"><?php foreach($comisiones as $co):?><label class="checkbox-label"><input type="checkbox" class="comisionSim" value="<?=(int)$co['id']?>" data-pct="<?=h($co['porcentaje'])?>" data-fijo="<?=h($co['cargo_fijo'])?>" data-iva="<?=h($co['iva_porcentaje'])?>" data-producto="<?=(int)($co['producto_id']??0)?>" data-categoria="<?=h($co['categoria'])?>" data-base="<?=h($co['base_calculo'])?>" data-moneda="<?=h($co['moneda'])?>"><span><?=h($co['nombre'])?> <small>(<?=h(str_replace('_',' ',$co['categoria']))?> · <?=number_format((float)$co['porcentaje'],2,',','.')?>% + <?=number_format((float)$co['cargo_fijo'],2,',','.')?>)</small></span></label><?php endforeach;?></div><?php endif;?></div></div></section>
<div class="actions"><button type="button" id="btnCalcular">Calcular y comparar escenarios</button><button type="button" class="btn-secondary" id="btnLimpiar">Restablecer</button></div><div id="erroresSim" class="error validation" role="alert" aria-live="polite"></div></section>
<section class="panel" id="resultados" hidden><h2>Resultados comparados</h2><div id="resultadosGrid" class="scenario-grid"></div><h3>Comparación visual de ganancia / pérdida</h3><div id="graficoEscenarios" aria-label="Gráfico comparativo de resultados"></div><div class="table-wrap" style="margin-top:16px"><table class="sim-table"><thead><tr><th>Indicador</th><th>Escenario 1</th><th>Escenario 2</th><th>Escenario 3</th></tr></thead><tbody id="tablaComparacion"></tbody></table></div><p class="method-note"><b>Metodología:</b> costo total = costos fijos + indirectos + mano de obra + (costo variable unitario × volumen). Costo unitario = costo total ÷ volumen. Precio sugerido = costo unitario ÷ (1 − margen esperado). El margen se calcula sobre el precio de venta, no como recargo sobre el costo. Contribución unitaria = precio de venta − costo variable unitario − comisiones variables por unidad. Las comisiones fijas se suman a los costos fijos del período. Punto de equilibrio (unidades) = costos fijos del período ÷ contribución unitaria. Facturación de equilibrio = unidades de equilibrio × precio de venta.</p></section>
</main></div>
<script>
const productoData = <?=json_encode(array_map(function($p)use($costosProducto){return ['id'=>(int)$p['id'],'nombre'=>$p['nombre'],'unidad'=>$p['unidad'],'moneda'=>$p['moneda'],'volumen'=>(float)$p['volumen_esperado'],'margen'=>(float)$p['margen_porcentaje'],'precio'=>$p['precio_manual']===null?'':(float)$p['precio_manual'],'horas'=>(float)$p['horas_trabajo'],'valorHora'=>(float)$p['valor_hora'],'costos'=>$costosProducto[(int)$p['id']]];},$productos),JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
const monedaFmt = n => new Intl.NumberFormat('es-AR',{style:'currency',currency:document.getElementById('moneda').value,maximumFractionDigits:2}).format(n);
const escenarios = [...document.querySelectorAll('.scenario-card')];
function setCampo(card,campo,valor){const el=card.querySelector(`[data-field="${campo}"]`);if(el)el.value=valor??0;}
function cargarBase(){const id=Number(document.getElementById('producto').value||0);const p=productoData.find(x=>x.id===id);document.getElementById('nombre').value=p?p.nombre:'';document.getElementById('unidad').value=p?p.unidad:'unidad';document.getElementById('moneda').value=p?p.moneda:<?=json_encode($config['moneda'])?>;const c=p?p.costos:{fixed:0,variable:0,indirect:0,labor:0};const vals={volumen:p?p.volumen:100,margen:p?p.margen:30,fijos:c.fixed,variable:c.variable,indirectos:c.indirect,laborRegistrada:c.labor,horas:p?p.horas:0,valorHora:p?p.valorHora:0,precioManual:p?p.precio:''};escenarios.forEach(card=>Object.entries(vals).forEach(([k,v])=>setCampo(card,k,v)));
// Se precargan tres escenarios distintos y editables para facilitar la comparación.
const base=escenarios[0];const read=k=>Number(base.querySelector('[data-field="'+k+'"]').value||0);
const alt2={volumen:read('volumen')*.9,margen:read('margen'),fijos:read('fijos')*1.1,variable:read('variable')*1.1,indirectos:read('indirectos')*1.1,laborRegistrada:read('laborRegistrada'),horas:read('horas'),valorHora:read('valorHora'),precioManual:''};
const alt3={volumen:read('volumen')*1.15,margen:Math.min(90,read('margen')+5),fijos:read('fijos')*.95,variable:read('variable')*.9,indirectos:read('indirectos')*.95,laborRegistrada:read('laborRegistrada'),horas:read('horas'),valorHora:read('valorHora'),precioManual:''};
[alt2,alt3].forEach((obj,i)=>Object.entries(obj).forEach(([k,v])=>setCampo(escenarios[i+1],k,v)));document.getElementById('erroresSim').classList.remove('show');document.getElementById('resultados').hidden=true;}
document.getElementById('producto').addEventListener('change',cargarBase);
function leerEscenario(card,idx){const v={};card.querySelectorAll('[data-field]').forEach(el=>{const raw=el.value.trim();v[el.dataset.field]=raw===''?null:Number(raw);});const nombre=['Base','Alternativo 2','Alternativo 3'][idx];for(const [k,n] of Object.entries(v)){if(n!==null&&(!Number.isFinite(n)||n<0))throw new Error(`${nombre}: el campo ${k} debe ser un número válido igual o mayor a cero.`);}if(v.volumen===null||v.volumen<=0)throw new Error(`${nombre}: el volumen del período debe ser mayor que cero.`);if(v.margen===null||v.margen>90)throw new Error(`${nombre}: el margen esperado debe estar entre 0 y 90%.`);if(v.precioManual!==null&&v.precioManual===0)throw new Error(`${nombre}: el precio manual debe ser mayor que cero o quedar vacío para usar el sugerido.`);if(v.fijos===null||v.variable===null||v.indirectos===null||v.laborRegistrada===null||v.horas===null||v.valorHora===null)throw new Error(`${nombre}: completá todos los datos de costos, usando cero cuando no corresponda.`);return v;}
function calcular(v,idx){const labor=v.laborRegistrada+(v.horas*v.valorHora);const fijosPeriodo=v.fijos+v.indirectos+labor;const costoBase=fijosPeriodo+v.variable*v.volumen;const costoUnitario=costoBase/v.volumen;const margen=v.margen/100;const sugerido=margen<1?costoUnitario/(1-margen):null;const precioOriginal=v.precioManual!==null?v.precioManual:sugerido;if(precioOriginal===null||!Number.isFinite(precioOriginal))throw new Error(`Escenario ${idx+1}: no se pudo obtener un precio sugerido.`);let precio=precioOriginal;let promoNombre='Sin promoción';const productoId=Number(document.getElementById('producto').value||0);let promo=document.getElementById('promocionSim').selectedOptions[0];if(promo&&promo.value){if(!productoId)throw new Error('Elegí un producto registrado para aplicar una promoción.');if(promo.dataset.alcance==='todos'){const individual=[...document.getElementById('promocionSim').options].find(o=>o.value&&o.dataset.alcance==='individual'&&(o.dataset.productos||'').split(',').map(Number).includes(productoId));if(individual)promo=individual;}const asignados=(promo.dataset.productos||'').split(',').filter(Boolean).map(Number);if(!asignados.includes(productoId)&&promo.dataset.futuros!=='1')throw new Error('La promoción elegida no está asignada al producto seleccionado.');const pv=Number(promo.dataset.valor||0);if(promo.dataset.tipo==='porcentaje')precio=precioOriginal*(1-pv/100);else if(promo.dataset.tipo==='fijo')precio=precioOriginal-pv;else if(promo.dataset.tipo==='mayorista'&&v.volumen>=Number(promo.dataset.minimo||0))precio=precioOriginal*(1-pv/100);else if(promo.dataset.tipo==='combo'){const compra=pv,bonif=Number(promo.dataset.bonif||0);if(compra>0&&bonif>0)precio=precioOriginal*compra/(compra+bonif);}if(precio<0)throw new Error('La promoción supera el precio de venta.');promoNombre=promo.textContent.trim();}const operaciones=Number(document.getElementById('operacionesSim').value||0);if(!Number.isFinite(operaciones)||operaciones<0)throw new Error('La cantidad de operaciones debe ser igual o mayor a cero.');let comisionTotal=0,comisionFija=0,comisionVariableUnidad=0;const seleccionadas=[...document.querySelectorAll('.comisionSim:checked')];seleccionadas.forEach(c=>{const pid=Number(c.dataset.producto||0);if(pid>0&&pid!==productoId)return;const cat=c.dataset.categoria;if(pid===0&&productoId>0&&seleccionadas.some(x=>Number(x.dataset.producto||0)===productoId&&x.dataset.categoria===cat))return;if(c.dataset.moneda!==document.getElementById('moneda').value)return;const basePrecio=c.dataset.base==='precio_sin_descuento'?precioOriginal:precio;const pct=Number(c.dataset.pct||0)/100*(1+Number(c.dataset.iva||0)/100);const fijo=Number(c.dataset.fijo||0)*operaciones*(1+Number(c.dataset.iva||0)/100);comisionVariableUnidad+=basePrecio*pct;comisionFija+=fijo;comisionTotal+=basePrecio*v.volumen*pct+fijo;});const ingresos=precio*v.volumen;const costoTotal=costoBase+comisionTotal;const ganancia=ingresos-costoTotal;const contribucion=precio-v.variable-comisionVariableUnidad;const eq=contribucion>0?Math.ceil((fijosPeriodo+comisionFija)/contribucion):null;const facturacionEq=eq===null?null:eq*precio;return {nombre:['Base','Alternativo 2','Alternativo 3'][idx],...v,labor,fijosPeriodo,costoTotal,costoUnitario,sugerido,precioOriginal,precio,ingresos,ganancia,contribucion,eq,facturacionEq,comisionTotal,promoNombre,margenReal:ingresos>0?ganancia/ingresos*100:0};}
function resultadoCard(r){const estado=r.ganancia>0?'Rentable':r.ganancia<0?'Pérdida':'En equilibrio';const k=[['Costo total',monedaFmt(r.costoTotal)],['Comisiones estimadas',monedaFmt(r.comisionTotal)],['Costo unitario',monedaFmt(r.costoUnitario)],['Precio sugerido',monedaFmt(r.sugerido)],['Precio aplicado',monedaFmt(r.precio)],['Promoción aplicada',escapeHtml(r.promoNombre)],['Ingresos estimados',monedaFmt(r.ingresos)],['Ganancia / pérdida',monedaFmt(r.ganancia)],['Margen real',r.margenReal.toFixed(2)+'%'],['Contribución por unidad',monedaFmt(r.contribucion)],['Punto de equilibrio',r.eq===null?'No se alcanza':r.eq.toLocaleString('es-AR')+' unidades'],['Facturación de equilibrio',r.facturacionEq===null?'No se alcanza':monedaFmt(r.facturacionEq)]];return `<article class="scenario-result"><h3>${r.nombre} · <span class="${r.ganancia>=0?'positive':'negative'}">${estado}</span></h3><div class="kpis">${k.map(([a,b])=>`<div class="kpi"><small>${a}</small><b>${b}</b></div>`).join('')}</div><p class="help">Volumen: ${r.volumen} ${escapeHtml(document.getElementById('unidad').value)} · Margen objetivo: ${r.margen}% · Mano de obra: ${monedaFmt(r.labor)}</p></article>`;}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function mostrar(rs){document.getElementById('resultadosGrid').innerHTML=rs.map(resultadoCard).join('');const max=Math.max(1,...rs.map(r=>Math.abs(r.ganancia)));document.getElementById('graficoEscenarios').innerHTML=rs.map(r=>{const w=Math.max(1,Math.abs(r.ganancia)/max*100);return `<div class="chart-row"><b>${r.nombre}</b><div class="chart-track"><div class="chart-bar ${r.ganancia<0?'loss':''}" style="width:${w}%"></div></div><span class="${r.ganancia>=0?'positive':'negative'}">${monedaFmt(r.ganancia)}</span></div>`;}).join('');const filas=[['Volumen',r=>r.volumen+' '+escapeHtml(document.getElementById('unidad').value)],['Costos fijos + indirectos + mano de obra',r=>monedaFmt(r.fijosPeriodo)],['Costos variables totales',r=>monedaFmt(r.variable*r.volumen)],['Costo total',r=>monedaFmt(r.costoTotal)],['Costo unitario',r=>monedaFmt(r.costoUnitario)],['Margen esperado',r=>r.margen+'%'],['Precio sugerido',r=>monedaFmt(r.sugerido)],['Precio aplicado',r=>monedaFmt(r.precio)],['Ganancia / pérdida',r=>monedaFmt(r.ganancia)],['Punto de equilibrio',r=>r.eq===null?'No se alcanza':r.eq+' unidades'],['Facturación de equilibrio',r=>r.facturacionEq===null?'No se alcanza':monedaFmt(r.facturacionEq)]];document.getElementById('tablaComparacion').innerHTML=filas.map(([label,fn])=>`<tr><th>${label}</th>${rs.map(r=>`<td>${fn(r)}</td>`).join('')}</tr>`).join('');document.getElementById('resultados').hidden=false;document.getElementById('resultados').scrollIntoView({behavior:'smooth',block:'start'});}
document.getElementById('btnCalcular').addEventListener('click',()=>{const box=document.getElementById('erroresSim');try{if(!document.getElementById('nombre').value.trim())throw new Error('Ingresá un nombre para el producto o servicio.');if(!document.getElementById('unidad').value.trim())throw new Error('Indicá la unidad de venta (unidad, kg, hora, servicio, etc.).');const rs=escenarios.map((card,i)=>calcular(leerEscenario(card,i),i));mostrar(rs);box.classList.remove('show');box.textContent='';}catch(e){box.textContent=e.message;box.classList.add('show');document.getElementById('resultados').hidden=true;}});
document.getElementById('btnLimpiar').addEventListener('click',()=>{document.getElementById('producto').value='';document.getElementById('promocionSim').value='';document.getElementById('operacionesSim').value='1';document.querySelectorAll('.comisionSim').forEach(c=>c.checked=false);cargarBase();});
cargarBase();
</script></body></html>
